function esc(s) {
  return s.replace(/'/g, "\\'").replace(/\\/g, '\\\\');
}

function findLi(t) {
  return "Array.from(document.querySelectorAll('.todo-list li')).filter(function(l){var lb=l.querySelector('div.view label');return lb&&lb.textContent==='" + esc(t) + "';})[0]";
}

function liExists(t) { return findLi(t) + '!==undefined'; }
function findToggle(t) { return "(function(){var li="+findLi(t)+";return li?li.querySelector('div.view input.toggle'):null;})()"; }
function findDes(t) { return "(function(){var li="+findLi(t)+";return li?li.querySelector('div.view button.destroy'):null;})()"; }
function findLabel(t) { return "(function(){var li="+findLi(t)+";return li?li.querySelector('div.view label'):null;})()"; }
function liClass(t,c){ return "(function(){var li="+findLi(t)+";return li?li.classList.contains('"+esc(c)+"'):false;})()"; }
function toggleChk(t){ return "(function(){var t="+findToggle(t)+";return t?t.checked:false;})()"; }
function mapSel(id){if(id==='#main')return '.main';if(id==='#footer')return '.footer';return id;}

